import React, { useState } from "react";
import "./App.css"; // Import CSS for animations

const TicTacToe = () => {
  const [board, setBoard] = useState(Array(9).fill(null));
  const [isXNext, setIsXNext] = useState(true);
  const [flipped, setFlipped] = useState(Array(9).fill(false)); // Track flipped state

  const calculateWinner = (squares) => {
    const lines = [
      [0, 1, 2],
      [3, 4, 5],
      [6, 7, 8],
      [0, 3, 6],
      [1, 4, 7],
      [2, 5, 8],
      [0, 4, 8],
      [2, 4, 6],
    ];
    for (let line of lines) {
      const [a, b, c] = line;
      if (squares[a] && squares[a] === squares[b] && squares[a] === squares[c]) {
        return squares[a];
      }
    }
    return null;
  };

  const handleClick = (index) => {
    if (board[index] || calculateWinner(board)) return;
    const newBoard = [...board];
    const newFlipped = [...flipped];

    newBoard[index] = isXNext ? "X" : "O";
    newFlipped[index] = true; // Flip the card when clicked

    setBoard(newBoard);
    setFlipped(newFlipped);
    setIsXNext(!isXNext);
  };

  const handleReset = () => {
    setBoard(Array(9).fill(null));
    setFlipped(Array(9).fill(false)); // Reset flip state
    setIsXNext(true);
  };

  const winner = calculateWinner(board);
  const status = winner
    ? `Winner: ${winner}`
    : board.includes(null)
    ? `Next Player: ${isXNext ? "X" : "O"}`
    : "Draw!";

  return (
    <div className="game-container">
      <h1>Tic-Tac-Toe</h1>
      <div className="board">
        {board.map((value, index) => (
          <div
            key={index}
            className={`card ${flipped[index] ? "flipped" : ""}`}
            onClick={() => handleClick(index)}
          >
            <div className="card-inner">
              <div className="card-front"></div>
              <div className="card-back">{value}</div>
            </div>
          </div>
        ))}
      </div>
      <h2>{status}</h2>
      <button className="reset-button" onClick={handleReset}>
        Reset Game
      </button>
    </div>
  );
};


const GRID_SIZE = 5; // 5x5 grid

const HeroGame = () => {
  const [position, setPosition] = useState({ x: 2, y: 2 }); // Start in the center

  const moveHero = (dx, dy) => {
    setPosition((prev) => {
      let newX = Math.max(0, Math.min(GRID_SIZE - 1, prev.x + dx));
      let newY = Math.max(0, Math.min(GRID_SIZE - 1, prev.y + dy));
      return { x: newX, y: newY };
    });
  };

  useEffect(() => {
    const handleKeyDown = (event) => {
      switch (event.key) {
        case "ArrowUp":
        case "w":
          moveHero(0, -1);
          break;
        case "ArrowDown":
        case "s":
          moveHero(0, 1);
          break;
        case "ArrowLeft":
        case "a":
          moveHero(-1, 0);
          break;
        case "ArrowRight":
        case "d":
          moveHero(1, 0);
          break;
        default:
          break;
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  return (
    <div className="game-container">
      <h1>Hero Movement Game</h1>
      <div className="grid">
        {Array.from({ length: GRID_SIZE }).map((_, row) =>
          Array.from({ length: GRID_SIZE }).map((_, col) => (
            <div key={`${row}-${col}`} className="cell">
              {position.x === col && position.y === row && <div className="hero">🦸</div>}
            </div>
          ))
        )}
      </div>
      <p>Use Arrow Keys or W A S D to move the hero.</p>
    </div>
  );
};

export default HeroGame;
// export default TicTacToe;
